/* Sukoon prototype: private recovery tools, no diagnostic inference or autonomous action. */
(function(){
 'use strict';
 const M=window.SukoonModel,T=(en,hi)=>document.documentElement.lang==='hi'?hi:en,E=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let modalNumber=0,state={},owner=null,vault=null,data=null,root=null,tab='today',exists=false,busy=false,selected=null,weekOffset=0,config={people:[],reminders:false,awake_available:false},household={requests:[],duties:[]},cloudRevision=null,voice=null,muted=false,recorder=null,recordStream=null,recordedAudio=null,urls=[],toolTimer=null,breathTimer=null,sessionEnd=0,sessionStep=-1,night=false,joined=false,sessionEpoch=0,lastTouch=Date.now(),lastRemote=0,presenceTimer=null,wizard=null,modal=null,crisis=false;
 const $=selector=>root?.querySelector(selector),language=()=>document.documentElement.lang==='hi'?'hi':'en',guest=()=>!!state.user?.guest||!!localStorage.getItem('dai_guest'),real=()=>owner&&owner!=='guest'&&!guest(),active=()=>location.hash==='#sukoon';
 const api=(path,options)=>window.DaiAPI?.apiRequest(path,options),notice=text=>{if($('[data-sk-status]'))$('[data-sk-status]').textContent=text;};
 const buttons=[['today','Today','आज'],['week','Your week','आपका सप्ताह'],['rest','Rest','आराम'],['letters','Open when…','जब ज़रूरत हो…'],['together','Together','साथ'],['night','Night sky','रात का आकाश']];
 const label=id=>M.weather.find(w=>w.id===id)?.[language()]||T('Not recorded','दर्ज नहीं');
 function weatherIcon(id){const paths={clear:'<circle cx="16" cy="16" r="6"/><path d="M16 2v4m0 20v4M2 16h4m20 0h4M6 6l3 3m14 14 3 3M6 26l3-3M23 9l3-3"/>',haze:'<circle cx="21" cy="11" r="5"/><path d="M21 1v2m8 8h2M27 5l2-2M4 25h20a5 5 0 0 0 0-10 8 8 0 0 0-15-1 5.5 5.5 0 0 0-5 11Z"/>',cloud:'<path d="M6 25h19a5 5 0 0 0-1-10 8 8 0 0 0-15-1 5.5 5.5 0 0 0-3 11Z"/>',rain:'<path d="M6 20h19a5 5 0 0 0-1-10 8 8 0 0 0-15-1 5.5 5.5 0 0 0-3 11ZM10 25l-1 4m9-4-1 4m9-4-1 4"/>',storm:'<path d="M5 18h20a5 5 0 0 0-1-10A8 8 0 0 0 9 7a5.5 5.5 0 0 0-4 11Zm7 3-3 5h5l-2 5m10-9-1 4"/>'};return '<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(paths[id]||'')+'</svg>';}
 const sky=()=>`<svg class="sk-landscape" viewBox="0 0 640 260" fill="none" role="img" aria-label="${T('A quiet illustrated landscape','एक शांत शैक्षिक दृश्य')}"><circle cx="465" cy="64" r="31" fill="currentColor" opacity=".16"/><path d="M0 199C100 100 174 242 282 167S464 110 640 195V260H0Z" fill="currentColor" opacity=".08"/><path d="M0 223C148 156 232 266 398 204S563 175 640 220V260H0Z" fill="currentColor" opacity=".11"/><path d="M0 248C130 226 195 246 325 230S518 222 640 245" stroke="currentColor" opacity=".16"/><path d="M78 75h34m-17-17v34M207 43h20m-10-10v20" stroke="currentColor" stroke-width="2" opacity=".18"/></svg>`;
 function header(){return `<header class="sk-header"><div><span class="sk-eyebrow">${T('Sukoon · Mind and rest','सुकून · मन और आराम')}</span><h1>${T('Room to exhale.','मन को थोड़ी जगह।')}</h1><p>${T('Short check-ins that help us support your recovery.','छोटे चेक-इन, आपकी रिकवरी में सहारा देने के लिए।')}</p></div><div class="sk-header-actions"><span class="sk-prototype">${T('Prototype · clinical review pending','प्रोटोटाइप · चिकित्सकीय समीक्षा बाकी')}</span><button data-sk-action="help" class="sk-help">${T('Help now','अभी मदद')}</button><button data-sk-action="hide" aria-label="${T('Quick hide and lock Sukoon','सुकून तुरंत बंद और लॉक करें')}">${T('Quick hide ↗','तुरंत बंद करें ↗')}</button></div></header>`;}
 function supportCard(){return `<section class="sk-support-card"><span class="sk-eyebrow">${T('Someone beside you','आपके साथ कोई')}</span><h2>${M.needsSupport(data.entries,M.today())?T('It’s been a heavy week.','यह सप्ताह भारी रहा है।'):T('You do not have to carry it alone.','सब कुछ अकेले सँभालना ज़रूरी नहीं।')}</h2><p>${T('Would you like to talk to someone about how you’ve been feeling?','आप कैसा महसूस कर रही हैं, क्या इस बारे में किसी से बात करना चाहेंगी?')}</p><div class="sk-actions"><button data-sk-action="care">${T('Talk to my care team','अपनी देखभाल टीम से बात करें')}</button><button data-sk-action="trusted">${T('Someone I trust','कोई भरोसेमंद व्यक्ति')}</button><button data-sk-action="later" class="sk-quiet">${T('Not now','अभी नहीं')}</button></div></section>`;}
 function locked(){return `<section class="sk-lock-card">${sky()}<div class="sk-lock-copy"><span class="sk-eyebrow">${T('A private space for every mother','हर माँ के लिए एक निजी जगह')}</span><h2>${exists?T('Welcome back.','फिर से स्वागत है।'):T('A little space, just for you.','थोड़ी जगह, सिर्फ आपके लिए।')}</h2><p>${T('Your notes, letters and check-ins are encrypted on this device. Your passphrase stays with you.','आपके नोट, पत्र और चेक-इन इस डिवाइस पर एन्क्रिप्टेड रहते हैं। पासफ़्रेज़ केवल आपके पास रहता है।')}</p><form data-sk-form="unlock"><label>${T('Private passphrase','निजी पासफ़्रेज़')}<input name="pass" type="password" minlength="12" maxlength="128" required autocomplete="${exists?'current-password':'new-password'}"></label>${!exists?`<label>${T('Repeat passphrase','पासफ़्रेज़ दोहराएँ')}<input name="repeat" type="password" minlength="12" maxlength="128" required autocomplete="new-password"></label><label class="sk-check"><input name="device" type="checkbox" required>${T('This is my private device.','यह मेरा निजी डिवाइस है।')}</label>`:''}<button class="sk-primary" type="submit">${exists?T('Open my space','अपनी जगह खोलें'):T('Create my private space','अपनी निजी जगह बनाएँ')}</button></form><small>${T('At least 12 characters. A forgotten passphrase cannot be recovered. Optional encrypted backup is available after unlocking.','कम से कम 12 अक्षर। भूला हुआ पासफ़्रेज़ वापस नहीं मिल सकता। खोलने के बाद एन्क्रिप्टेड बैकअप चुन सकती हैं।')}</small></div></section>`;}
 function todayView(){const entry=data.entries.find(e=>e.date===M.today()),answer=M.weather.find(w=>w.id===(selected||entry?.weather));return `<section class="sk-today-card">${sky()}<div class="sk-today-copy"><span class="sk-eyebrow">${T('A moment for you','आपके लिए एक पल')}</span><h2>${T('How are you carrying today?','आज मन पर कितना भार है?')}</h2><div class="sk-weather-choices" role="group" aria-label="${T('How today feels','आज कैसा लग रहा है')}">${M.weather.map(w=>`<button data-sk-weather="${w.id}" aria-pressed="${(selected||entry?.weather)===w.id}"><span aria-hidden="true">${weatherIcon(w.id)}</span><span>${w[language()]}</span></button>`).join('')}</div><form data-sk-form="mood"><label>${T('A line for yourself · optional','अपने लिए एक पंक्ति · वैकल्पिक')}<input name="note" maxlength="240" value="${E(entry?.note||'')}" placeholder="${T('What would help today?','आज क्या मदद करेगा?')}"></label><button class="sk-primary" type="submit">${T('Keep this moment','यह पल सहेजें')}</button></form>${answer?`<p class="sk-kind-reply" role="status">${answer.reply[language()==='hi'?1:0]}</p>`:''}</div></section><div class="sk-small-grid"><button class="sk-feature" data-sk-action="breathing"><span class="sk-feature-icon">◌</span><strong>${T('A quiet breath','साँस का विराम')}</strong><span>${T('Soft light. Nothing to finish.','नरम रोशनी। कुछ पूरा करना ज़रूरी नहीं।')}</span></button><button class="sk-feature" data-sk-action="wizard"><span class="sk-feature-icon">☾</span><strong>${T('Recovery check-in','रिकवरी चेक-इन')}</strong><span>${T('A standard postnatal questionnaire.','प्रसव के बाद का मानक प्रश्नपत्र।')}</span></button><button class="sk-feature" data-sk-tab="letters"><span class="sk-feature-icon">✉</span><strong>${T('A letter for tonight','आज रात के लिए एक पत्र')}</strong><span>${T('Words and voices you chose.','आपके चुने शब्द और आवाज़ें।')}</span></button></div>${invitation()}${supportCard()}`;}
 function deliveryDate(){return String(state.post?.delivery?.delivery_date||state.post?.delivery_date||'').slice(0,10);}
 function invitation(){return M.invitations(deliveryDate(),data.checkins).length?`<section class="sk-invitation"><span>☾</span><div><h3>${T('A small recovery check-in','एक छोटा रिकवरी चेक-इन')}</h3><p>${T('Alongside healing, feeding and rest, there is space for how you feel.','शरीर की रिकवरी, दूध पिलाने और आराम के साथ, मन की बात के लिए भी जगह है।')}</p></div><button data-sk-action="wizard">${T('When you are ready','जब आप तैयार हों')}</button></section>`:'';}
 function weekView(){const days=M.weekly(data.entries,M.today(),weekOffset);return `<section class="sk-week-card"><div class="sk-section-head"><div><span class="sk-eyebrow">${T('Weather inside','मन का मौसम')}</span><h2>${T('Every day has its own sky.','हर दिन का अपना आकाश।')}</h2></div><div class="sk-actions"><button data-sk-action="earlier" aria-label="${T('Earlier week','पिछला सप्ताह')}">←</button><button data-sk-action="newer" ${weekOffset===0?'disabled':''} aria-label="${T('Newer week','अगला सप्ताह')}">→</button></div></div>${sky()}<div class="sk-week-weather">${days.map(({date,entry})=>`<button data-sk-day="${date}" aria-label="${E(date+' · '+(entry?label(entry.weather):T('Not recorded','दर्ज नहीं')))}"><span class="sk-weather-day">${new Date(date+'T12:00:00').toLocaleDateString(language(),{weekday:'short'})}</span><span class="sk-weather-symbol" aria-hidden="true">${entry?weatherIcon(entry.weather):'·'}</span><strong>${entry?label(entry.weather):T('No entry','दर्ज नहीं')}</strong><small>${new Date(date+'T12:00:00').toLocaleDateString(language(),{day:'numeric',month:'short'})}</small></button>`).join('')}</div><p class="sk-note">${T('Only what you chose to record. Missing days are left open.','केवल आपकी दर्ज की गई बातें। छूटे दिन खाली रहते हैं।')}</p></section>${supportCard()}`;}
 function restView(){return `<div class="sk-small-grid sk-rest-grid"><section class="sk-card"><span class="sk-feature-icon">◌</span><h2>${T('A quiet breath','साँस का विराम')}</h2><p>${T('Follow the soft light only if comfortable. No breath holds. Vibration is optional and browser-dependent.','आराम लगे तभी रोशनी का साथ दें। साँस न रोकें। कंपन वैकल्पिक है और ब्राउज़र पर निर्भर है।')}</p><button data-sk-action="breathing" class="sk-primary">${T('Begin a pause','विराम शुरू करें')}</button></section><section class="sk-card"><span class="sk-feature-icon">◖</span><h2>${T('Five minutes of grounding','पाँच मिनट का विराम')}</h2><p>${T('Prepared words from Dhruv, with quiet pauses. Prototype script for clinical review.','ध्रुव के तैयार शब्द और शांत विराम। चिकित्सकीय समीक्षा के लिए प्रोटोटाइप स्क्रिप्ट।')}</p><button data-sk-action="grounding" class="sk-primary">${T('Listen with Dhruv','ध्रुव के साथ सुनें')}</button></section><section class="sk-card"><span class="sk-feature-icon">☾</span><h2>${T('A little protected rest','आराम की थोड़ी जगह')}</h2><p>${T('Ask your chosen person, then use a quiet rest timer. This browser cannot silence your phone or block calls.','अपने चुने व्यक्ति से कहें, फिर शांत आराम टाइमर चलाएँ। ब्राउज़र फोन की आवाज़ या कॉल बंद नहीं कर सकता।')}</p><button data-sk-action="tapout" class="sk-primary">${T('Ask for a hand','सहारा माँगें')}</button><button data-sk-action="sleep">${T('Rest timer only','केवल आराम टाइमर')}</button></section></div><section class="sk-card"><h2>${T('Words that help tonight','आज रात सहारा देने वाले शब्द')}</h2><div class="sk-tip-grid"><article><h3>${T('For a partner','साथी के लिए')}</h3><p>${T('Ask “What can I take off your hands?” Bring water, prepare food, change a diaper or take a household task.','पूछें: “आपका कौन-सा काम मैं सँभालूँ?” पानी लाएँ, खाना तैयार करें, डायपर बदलें या घर का काम करें।')}</p></article><article><h3>${T('For family and elders','परिवार और बड़ों के लिए')}</h3><p>${T('Listen before advising. Avoid comparisons and “you should be happy.” Try “I am here. What would help?”','सलाह से पहले सुनें। तुलना या “खुश होना चाहिए” न कहें। कहें: “मैं साथ हूँ। क्या मदद करेगा?”')}</p></article></div></section>`;}
 function lettersView(){return `<section class="sk-section-head"><div><span class="sk-eyebrow">${T('Open when…','जब ज़रूरत हो…')}</span><h2>${T('Keep a familiar voice close.','एक परिचित आवाज़ पास रखें।')}</h2><p>${T('Write or record with permission. Nothing is sent to family or to AI.','अनुमति लेकर लिखें या रिकॉर्ड करें। परिवार या AI को कुछ नहीं भेजा जाता।')}</p></div><button data-sk-action="newletter" class="sk-primary">${T('Add an envelope','एक पत्र जोड़ें')}</button></section><div class="sk-envelope-grid">${data.letters.length?data.letters.map(l=>`<button class="sk-envelope" data-sk-letter="${E(l.id)}"><span aria-hidden="true">✉</span><strong>${E(l.title)}</strong><small>${T('From','की ओर से')} ${E(l.author)}</small><span>${l.audio?T('Voice inside','अंदर आवाज़ है'):T('Words inside','अंदर शब्द हैं')}</span></button>`).join(''):`<section class="sk-empty">${sky()}<h3>${T('An envelope for a harder night.','भारी रात के लिए एक पत्र।')}</h3><p>${T('A note from your earlier self, or someone you trust.','अपने पुराने किसी दिन का नोट, या किसी भरोसेमंद व्यक्ति के शब्द।')}</p></section>`}</div><section class="sk-card"><h2>${T('Mothers’ voices · concept preview','माँओं की आवाज़ें · उदाहरण')}</h2><p>${T('These are clearly labelled fictional stories, not live community recordings. Real stories need permission and moderation.','ये स्पष्ट रूप से चिह्नित उदाहरण कहानियाँ हैं, समुदाय की वास्तविक रिकॉर्डिंग नहीं। वास्तविक कहानियों के लिए अनुमति और समीक्षा चाहिए।')}</p><div class="sk-actions">${M.stories.map((story,i)=>`<button data-sk-story="${i}">${story.title[language()==='hi'?1:0]} ▶</button>`).join('')}</div></section>`;}
 function togetherView(){const duties=real()?household.duties:data.duties,counts={};for(const duty of duties){const person=duty.person||'mother';counts[person]=(counts[person]||0)+1;}const labels={mother:T('You','आप'),partner:T('Partner','साथी'),parent:T('Parent or elder','माता-पिता या बड़े'),caregiver:T('Caregiver','देखभाल करने वाला'),relative:T('Relative','रिश्तेदार'),sibling:T('Sibling','भाई या बहन'),other:T('Trusted person','भरोसेमंद व्यक्ति')};const total=duties.length,segments=Object.entries(counts);let at=0;const stops=segments.map(([person,count],i)=>{const start=at;at+=count/total*100;return `var(--sk-load-${Math.min(i,3)}) ${start}% ${at}%`;}).join(',');return `<section class="sk-card"><span class="sk-eyebrow">${T('The invisible load','अनदेखी मेहनत')}</span><h2>${T('Small tasks, shared.','छोटे काम, साथ मिलकर।')}</h2><p>${T('Only logged tasks are counted. This does not measure total effort, time or fairness.','केवल दर्ज काम गिने जाते हैं। यह कुल मेहनत, समय या बराबरी का माप नहीं है।')}</p><div class="sk-load-layout"><div class="sk-load-ring ${total?'':'is-empty'}" style="${total?'background:conic-gradient('+stops+')':''}" role="img" aria-label="${E(total?segments.map(([p,n])=>(labels[p]||labels.other)+': '+n).join(', '):T('No shared tasks recorded','साझा काम दर्ज नहीं'))}"><div><strong>${total?total:'—'}</strong><span>${T('recorded tasks','दर्ज काम')}</span></div></div><div class="sk-load-legend">${segments.map(([person,count],i)=>`<p><i style="background:var(--sk-load-${Math.min(i,3)})"></i>${labels[person]||labels.other}<strong>${count}</strong></p>`).join('')||`<p>${T('Leave the picture open until someone logs a task.','कोई काम दर्ज होने तक यह दृश्य खाली रहेगा।')}</p>`}</div></div><h3>${T('I handled…','मैंने सँभाला…')}</h3><div class="sk-actions">${Object.entries(M.duties).map(([id,names])=>`<button data-sk-duty="${id}">${names[language()==='hi'?1:0]}</button>`).join('')}</div></section><section class="sk-card"><div class="sk-section-head"><h2>${T('Ask for a hand','सहारा माँगें')}</h2><button data-sk-action="tapout" class="sk-primary">${T('Tap out','थोड़ा आराम माँगें')}</button></div><p>${T('Only an accepted support person with practical-support permission can receive a request. They never see your entries.','केवल व्यावहारिक सहयोग की अनुमति वाला स्वीकार किया गया व्यक्ति अनुरोध पा सकता है। वे आपकी निजी बातें नहीं देखते।')}</p>${household.requests.map(r=>`<article class="sk-request"><span>${E(r.relationship)} · ${r.minutes} ${T('minutes requested','मिनट का अनुरोध')}</span><strong>${({requested:T('Requested · not yet accepted','अनुरोध भेजा · अभी स्वीकार नहीं'),accepted:T('Accepted by your person','आपके व्यक्ति ने स्वीकार किया'),done:T('Marked done by helper','सहायक ने पूरा दर्ज किया'),cancelled:T('Cancelled','रद्द')})[r.status]}</strong>${['requested','accepted'].includes(r.status)?`<button data-sk-cancel="${E(r.id)}">${T('Cancel request','अनुरोध रद्द करें')}</button>`:''}</article>`).join('')||`<p class="sk-note">${T('No recorded rest requests.','आराम के अनुरोध दर्ज नहीं हैं।')}</p>`}<button data-sk-action="family">${T('Manage my support circle ↗','सहयोग समूह सँभालें ↗')}</button></section>`;}
 function nightView(){return `<section class="sk-night-sky"><div class="sk-stars" aria-hidden="true">${Array.from({length:28},(_,i)=>`<i style="left:${(i*37+11)%94+3}%;top:${(i*29+17)%76+4}%;animation-delay:${i%7}s"></i>`).join('')}</div><span class="sk-moon" aria-hidden="true">☾</span><div class="sk-night-copy"><span class="sk-eyebrow">${T('Awake with you','आपके साथ जागती रात')}</span><h2>${T('A quieter sky for a long night.','लंबी रात के लिए एक शांत आकाश।')}</h2><p data-sk-awake>${T('Illustrated sky. Live counts are not connected.','यह चित्रित आकाश है। लाइव गिनती जुड़ी नहीं है।')}</p><div class="sk-actions"><button data-sk-action="nightdim">${night?T('Leave night mode','रात मोड बंद करें'):T('Dim this space','यह जगह मंद करें')}</button><button data-sk-action="grounding">${T('A quiet audio pause','शांत ऑडियो विराम')}</button></div>${config.awake_available?`<label class="sk-check"><input type="checkbox" data-sk-presence ${joined?'checked':''}>${T('Include me in the anonymous national count for five minutes. No location.','मुझे पाँच मिनट की गुमनाम राष्ट्रीय गिनती में जोड़ें। कोई स्थान साझा नहीं।')}</label>`:`<small>${T('Live counts are a feature-flagged prototype. Stars are decorative, not people or locations.','लाइव गिनती अभी वैकल्पिक प्रोटोटाइप है। तारे सजावट हैं, लोग या स्थान नहीं।')}</small>`}</div></section><section class="sk-card"><h2>${T('A familiar voice','एक परिचित आवाज़')}</h2><p>${T('Open a letter, or choose a prepared story. You can stop the sound at any time.','एक पत्र खोलें या तैयार कहानी चुनें। आवाज़ कभी भी रोक सकती हैं।')}</p><div class="sk-actions"><button data-sk-tab="letters">${T('Open my letters','मेरे पत्र खोलें')}</button>${M.stories.map((s,i)=>`<button data-sk-story="${i}">${s.title[language()==='hi'?1:0]} ▶</button>`).join('')}</div></section>`;}
 function privacy(){return `<details class="sk-privacy"><summary>${T('Who can see what?','कौन क्या देख सकता है?')}</summary><p>${T('Notes, letters and check-ins stay encrypted in this browser. An optional server backup contains ciphertext only. A chosen clinical result enters the existing DAI clinical record only after confirmation; that record follows DAI’s existing server storage and consent rules. Family receives only practical requests and task logs.','नोट, पत्र और चेक-इन इस ब्राउज़र में एन्क्रिप्टेड रहते हैं। वैकल्पिक सर्वर बैकअप में केवल एन्क्रिप्टेड डेटा है। पुष्टि के बाद ही चुना परिणाम DAI के मौजूदा क्लिनिकल रिकॉर्ड में जाता है; वहाँ मौजूदा भंडारण और सहमति नियम लागू होते हैं। परिवार को केवल व्यावहारिक अनुरोध और काम की जानकारी मिलती है।')}</p><p>${T('Locks when hidden or after five minutes idle. Quick hide cannot erase browser history. Entries are not continuously monitored.','छिपने या पाँच मिनट निष्क्रिय रहने पर लॉक होता है। तुरंत बंद करने से ब्राउज़र इतिहास नहीं मिटता। प्रविष्टियाँ लगातार निगरानी में नहीं रहतीं।')}</p><div class="sk-actions"><button data-sk-action="backup" ${!real()?'disabled':''}>${T('Save encrypted backup','एन्क्रिप्टेड बैकअप सहेजें')}</button><button data-sk-action="restore" ${!real()?'disabled':''}>${T('Restore backup','बैकअप वापस लाएँ')}</button><button data-sk-action="export">${T('Download encrypted copy','एन्क्रिप्टेड प्रति डाउनलोड करें')}</button><button data-sk-action="summary">${T('Review visit summary','मुलाकात का सार देखें')}</button><button data-sk-action="erase">${T('Delete private copies','निजी प्रतियाँ हटाएँ')}</button></div><label class="sk-check"><input data-sk-reminder type="checkbox" ${config.reminders?'checked':''} ${!real()?'disabled':''}>${T('Neutral in-app reminder: “Your evening check-in is ready.” Push and SMS are not connected here.','सामान्य इन-ऐप याद दिलाना: “शाम का चेक-इन तैयार है।” यहाँ पुश और SMS जुड़े नहीं हैं।')}</label></details>`;}
 function render(){if(!root||!active())return;if(crisis){renderCrisis();return;}root.classList.toggle('sk-night',night);root.innerHTML=header()+`<p class="sk-status" data-sk-status role="status" aria-live="polite"></p>`+(data?`<nav class="sk-tabs" aria-label="${T('Sukoon sections','सुकून के हिस्से')}">${buttons.map(([id,en,hi])=>`<button data-sk-tab="${id}" aria-current="${tab===id?'page':'false'}">${T(en,hi)}</button>`).join('')}</nav><div class="sk-content">${({today:todayView,week:weekView,rest:restView,letters:lettersView,together:togetherView,night:nightView})[tab]()}</div>${privacy()}<footer>${T('Your pace. Your choices. Support whenever you want it.','आपकी गति। आपकी पसंद। जब चाहें, सहारा।')}</footer>`:locked());if(tab==='night'&&data)refreshAwake();}
 async function save(){if(new TextEncoder().encode(JSON.stringify(data)).byteLength>4000000)throw Error(T('This private copy is full. Remove an audio letter or download a backup.','निजी प्रति भर गई है। कोई ऑडियो पत्र हटाएँ या बैकअप डाउनलोड करें।'));if(!vault?.isUnlocked())throw Error(T('Open your private space first.','पहले अपनी निजी जगह खोलें।'));await vault.save(data);}
 function navigate(panel){document.querySelector('.nav-item[data-panel="'+panel+'"]')?.click();}
 function stopTools(){sessionEpoch++;modal?.querySelectorAll('audio').forEach(audio=>{audio.pause();audio.removeAttribute('src');audio.load();});voice?.stop();clearInterval(toolTimer);clearInterval(breathTimer);toolTimer=breathTimer=null;sessionEnd=0;sessionStep=-1;try{navigator.vibrate?.(0);}catch{}if(recorder&&recorder.state!=='inactive')recorder.stop();recorder=null;recordStream?.getTracks().forEach(t=>t.stop());recordStream=null;recordedAudio=null;urls.forEach(URL.revokeObjectURL);urls=[];}
 function closeModal(){stopTools();const old=modal;modal=null;old?.close();old?.remove();}
 function lock(hide=false){sessionEpoch++;vault?.lock();data=null;selected=null;wizard=null;crisis=false;night=false;closeModal();if(joined&&real())void api('/patient/sukoon/presence',{method:'DELETE'});joined=false;clearTimeout(presenceTimer);presenceTimer=null;temporaryContact='';if(root&&!active())root.replaceChildren();else render();if(hide)navigate('dashboard');}
 function showModal(content){closeModal();modal=document.createElement('dialog');modal.className='sk-dialog';modal.innerHTML=`<div class="sk-dialog-tools"><button type="button" data-sk-modal-hide>${T('Quick hide','तुरंत बंद करें')}</button><button type="button" data-sk-modal-help>${T('Emergency help','आपातकालीन मदद')}</button><button class="sk-dialog-close" type="button" aria-label="${T('Close','बंद करें')}">×</button></div><div class="sk-dialog-body">${content}</div>`;document.body.append(modal);const heading=modal.querySelector('h2');if(heading){heading.id='sukoon-dialog-'+(++modalNumber);modal.setAttribute('aria-labelledby',heading.id);}modal.querySelector('.sk-dialog-close').onclick=closeModal;modal.querySelector('[data-sk-modal-hide]').onclick=()=>lock(true);modal.querySelector('[data-sk-modal-help]').onclick=()=>{closeModal();document.getElementById('sosBtn')?.click();};const node=modal;node.addEventListener('close',()=>{if(modal===node){stopTools();modal=null;}node.remove();},{once:true});modal.addEventListener('cancel',()=>stopTools());modal.showModal();return modal;}
 function trustedPhone(){return data?.contacts?.phone||temporaryContact||state.user?.emergency_contact_phone||'';}
 function phoneLink(phone,labelText){return /^[+\d ()-]{7,22}$/.test(phone||'')?`<a class="sk-button" href="tel:${E(phone.replace(/[^+\d]/g,''))}">${labelText}</a>`:'';}
 function renderCrisis(){closeModal();root.classList.remove('sk-night');root.innerHTML=header()+`<section class="sk-crisis" role="alert" tabindex="-1"><p data-sk-status role="status"></p><span class="sk-eyebrow">${T('Stay with someone','किसी के साथ रहें')}</span><h2>${T('You are not alone. Please get help now.','आप अकेली नहीं हैं। कृपया अभी मदद लें।')}</h2><p>${T('If you might hurt yourself or your baby, feel severely confused, have not slept for days, or see or hear things others do not, seek urgent in-person care. Ask someone you trust to stay with you. Do not wait for an app reply.','खुद को या शिशु को नुकसान पहुँचाने का डर हो, बहुत भ्रम हो, कई दिनों से नींद न आई हो या ऐसी चीज़ें दिखें-सुनें जो दूसरों को नहीं, तो तुरंत प्रत्यक्ष चिकित्सा मदद लें। किसी भरोसेमंद व्यक्ति से साथ रहने को कहें। ऐप के जवाब की प्रतीक्षा न करें।')}</p><div class="sk-crisis-actions">${phoneLink(trustedPhone(),T('Call my chosen person','अपने चुने व्यक्ति को कॉल करें'))}<button data-sk-action="trusted">${T('Choose a trusted contact','भरोसेमंद संपर्क चुनें')}</button>${phoneLink(data?.contacts?.hospital,T('Call my hospital','अस्पताल को कॉल करें'))}<button class="sk-sos" data-sk-action="sos">SOS · ${T('Emergency help','आपातकालीन मदद')}</button><a class="sk-button" href="tel:112">112 · ${T('Emergency response','आपातकालीन सहायता')}</a><a class="sk-button" href="tel:+9114416?oai_link_source=model_response_hotline">Tele-MANAS · 14416</a></div><p>${T('Tele-MANAS offers support. For immediate danger, use emergency care or SOS. Nothing has been sent to family automatically.','Tele-MANAS सहायता देता है। तुरंत खतरे में आपातकालीन सेवा या SOS लें। परिवार को अपने-आप कुछ नहीं भेजा गया है।')}</p><a href="https://telemanas.mohfw.gov.in/home?oai_link_source=model_response_hotline" target="_blank" rel="noopener">${T('Official Tele-MANAS information','Tele-MANAS की आधिकारिक जानकारी')} ↗</a><button data-sk-action="back">${T('Return to my space','अपनी जगह पर लौटें')}</button></section>`;$('.sk-crisis').focus();}
 function voiceState(status){if(status==='speaking')lastTouch=Date.now();const node=modal?.querySelector('[data-sk-audio-status]');if(node)node.textContent=({loading:T('Preparing Dhruv…','ध्रुव तैयार हो रहा है…'),speaking:T('Dhruv is speaking','ध्रुव बोल रहा है'),blocked:T('Tap Play to hear the prepared audio','तैयार आवाज़ सुनने के लिए चलाएँ दबाएँ'),error:T('Audio unavailable. The full script stays visible.','आवाज़ उपलब्ध नहीं। पूरी स्क्रिप्ट लिखी हुई है।'),ready:T('A quiet pause','एक शांत विराम')})[status]||'';}
 function playPrepared(text){if(muted)return;voice?.unlock();window.DhruvCompanion?.stop();voice?.speak(window.DaiI18n?.translate(text)||text,['hi','mr'].includes(document.documentElement.lang)?document.documentElement.lang:'en');}
 async function refreshRemote(){if(!real()||!active()||state.offline||navigator.onLine===false)return;lastRemote=Date.now();const token=sessionEpoch;const [c,h]=await Promise.all([api('/patient/sukoon'),api('/patient/sukoon/household')]);if(token!==sessionEpoch||!active())return;if(c)config=c;if(h)household=h;if(data&&['together','night'].includes(tab)&&!modal)render();}
 async function refreshAwake(){if(!config.awake_available||!real()||!active())return;const result=await api('/patient/sukoon/awake');if($('[data-sk-awake]'))$('[data-sk-awake]').textContent=result?.count?T(result.count+'+ opted-in sessions joined recently. National count; rounded for privacy.',result.count+'+ लोगों ने हाल में जुड़ना चुना। निजता के लिए पूर्णांक राष्ट्रीय गिनती।'):T('The count stays private until enough people join. Stars are illustrative.','पर्याप्त लोगों के जुड़ने तक गिनती निजी रहती है। तारे केवल चित्र हैं।');}
 function breathing(){const d=showModal(`<span class="sk-eyebrow">${T('A quiet breath','साँस का विराम')}</span><h2>${T('Only at your own pace.','केवल अपनी सहज गति पर।')}</h2><div class="sk-breath-orb" aria-hidden="true"></div><p data-sk-breath-caption>${T('Breathe gently. No need to match the light.','धीरे साँस लें। रोशनी की गति अपनाना ज़रूरी नहीं।')}</p><label class="sk-check"><input type="checkbox" data-sk-haptic>${T('Optional vibration','वैकल्पिक कंपन')}</label><p>${T('Stop if uncomfortable or dizzy. This does not follow your baby’s feeding rhythm.','असहज लगने या चक्कर आने पर रोक दें। यह शिशु के दूध पीने की गति का अनुसरण नहीं करता।')}</p><p class="sk-note" data-sk-haptic-note></p><button type="button" class="sk-primary" data-sk-breath-stop>${T('Finish this pause','यह विराम पूरा करें')}</button>`);let phase=0;d.querySelector('[data-sk-haptic-note]').textContent=typeof navigator.vibrate==='function'?T('Vibration depends on your browser and device.','कंपन ब्राउज़र और डिवाइस पर निर्भर है।'):T('Vibration is unavailable here. The light and words still work.','यहाँ कंपन उपलब्ध नहीं। रोशनी और शब्द काम करते हैं।');d.querySelector('[data-sk-breath-stop]').onclick=closeModal;breathTimer=setInterval(()=>{phase++;if(d.querySelector('[data-sk-haptic]').checked&&typeof navigator.vibrate==='function')navigator.vibrate(phase%2?35:70);},5000);}
 function grounding(){const d=showModal(`<span class="sk-eyebrow">${T('Five-minute pause','पाँच मिनट का विराम')}</span><h2>${T('A little room for right now.','अभी के लिए थोड़ी जगह।')}</h2><span class="sk-session-time" data-sk-session-time>5:00</span><p data-sk-audio-status role="status"></p><p class="sk-transcript" data-sk-session-copy>${E(M.grounding[0][language()==='hi'?1:0])}</p><div class="sk-actions"><button class="sk-primary" data-sk-session-play>${T('Start with Dhruv','ध्रुव के साथ शुरू करें')}</button><button data-sk-session-mute>${T('Mute audio','आवाज़ बंद करें')}</button><button data-sk-session-end>${T('Finish now','अभी पूरा करें')}</button></div><small>${T('Prepared prototype script; clinical sign-off pending. Includes quiet pauses. No microphone or analysis.','तैयार प्रोटोटाइप स्क्रिप्ट; चिकित्सकीय मंज़ूरी बाकी। शांत विराम शामिल हैं। माइक्रोफ़ोन या विश्लेषण नहीं।')}</small>`);d.querySelector('[data-sk-session-play]').onclick=()=>{if(sessionEnd){if(voice?.pending())voice.resume();else playPrepared(M.grounding[Math.max(0,sessionStep)][language()==='hi'?1:0]);return;}sessionEnd=Date.now()+300000;sessionStep=0;playPrepared(M.grounding[0][language()==='hi'?1:0]);toolTimer=setInterval(()=>{if(!modal)return;const remaining=Math.max(0,sessionEnd-Date.now()),totalSeconds=Math.ceil(remaining/1000),minutes=Math.floor(totalSeconds/60),seconds=totalSeconds%60;d.querySelector('[data-sk-session-time]').textContent=minutes+':'+String(seconds).padStart(2,'0');const index=Math.min(4,Math.floor((300000-remaining)/60000));if(index!==sessionStep){sessionStep=index;d.querySelector('[data-sk-session-copy]').textContent=M.grounding[index][language()==='hi'?1:0];playPrepared(M.grounding[index][language()==='hi'?1:0]);}if(!remaining){stopTools();d.querySelector('[data-sk-audio-status]').textContent=T('Your pause is complete. You can stop here.','आपका विराम पूरा हुआ। यहीं रुक सकती हैं।');}},500);};d.querySelector('[data-sk-session-mute]').onclick=()=>{muted=!muted;if(muted)voice?.stop();d.querySelector('[data-sk-session-mute]').textContent=muted?T('Unmute audio','आवाज़ चालू करें'):T('Mute audio','आवाज़ बंद करें');};d.querySelector('[data-sk-session-end]').onclick=closeModal;}
 function sleepTimer(){const d=showModal(`<div class="sk-sleep-fort"><span aria-hidden="true">☾</span><h2>${T('A small rest fort.','आराम की छोटी जगह।')}</h2><p>${T('This dims this view only. It cannot block phone calls or notifications. Keep needed care and emergency access available.','यह केवल इस दृश्य को मंद करता है। फोन कॉल या सूचनाएँ बंद नहीं कर सकता। ज़रूरी देखभाल और आपातकालीन मदद उपलब्ध रखें।')}</p><label>${T('Rest timer','आराम टाइमर')}<select data-sk-sleep-minutes><option value="15">15 ${T('minutes','मिनट')}</option><option value="30">30 ${T('minutes','मिनट')}</option><option value="60">60 ${T('minutes','मिनट')}</option><option value="120">120 ${T('minutes','मिनट')}</option></select></label><strong data-sk-rest-clock></strong><div class="sk-actions"><button data-sk-sleep-start>${T('Start quiet timer','शांत टाइमर शुरू करें')}</button><button data-sk-sleep-sos>SOS</button></div></div>`);d.querySelector('[data-sk-sleep-start]').onclick=()=>{clearInterval(toolTimer);const end=Date.now()+(+d.querySelector('[data-sk-sleep-minutes]').value)*60000;const tick=()=>{const n=Math.max(0,Math.ceil((end-Date.now())/1000));d.querySelector('[data-sk-rest-clock]').textContent=Math.floor(n/60)+':'+String(n%60).padStart(2,'0');if(n===0)clearInterval(toolTimer);};tick();toolTimer=setInterval(tick,1000);};d.querySelector('[data-sk-sleep-sos]').onclick=()=>{closeModal();document.getElementById('sosBtn')?.click();};}
 function letterForm(){const d=showModal(`<span class="sk-eyebrow">${T('Open when…','जब ज़रूरत हो…')}</span><h2>${T('Keep a little kindness.','थोड़ा अपनापन सहेजें।')}</h2><form data-sk-letter-form><label>${T('Open when…','जब…')}<select name="title"><option>${T('The night feels long','रात लंबी लगे')}</option><option>${T('I miss my earlier self','अपना पुराना रूप याद आए')}</option><option>${T('I need a familiar voice','परिचित आवाज़ चाहिए')}</option><option>${T('I need encouragement','हौसला चाहिए')}</option></select></label><label>${T('From','की ओर से')}<input name="author" maxlength="60" required value="${E(T('Me','मैं'))}"></label><label>${T('Your words · optional with audio','आपके शब्द · ऑडियो हो तो वैकल्पिक')}<textarea name="body" maxlength="2000" rows="4"></textarea></label><div class="sk-record-row"><button type="button" data-sk-record>${T('Record a voice note','आवाज़ रिकॉर्ड करें')}</button><button type="button" data-sk-record-stop disabled>${T('Stop recording','रिकॉर्डिंग रोकें')}</button></div><label>${T('Or choose an audio file · up to 700 KB','या ऑडियो चुनें · अधिकतम 700 KB')}<input type="file" name="audio" accept="audio/*"></label><p data-sk-record-status role="status"></p><label class="sk-check"><input type="checkbox" name="permission" required>${T('The person whose voice or words I am saving has agreed.','जिसकी आवाज़ या शब्द सहेज रही हूँ, उसने अनुमति दी है।')}</label><button class="sk-primary" type="submit">${T('Seal this envelope','यह पत्र सहेजें')}</button></form><small>${T('The microphone is used only while recording. Audio stays in your encrypted private space.','माइक्रोफ़ोन केवल रिकॉर्डिंग में इस्तेमाल होता है। ऑडियो आपकी एन्क्रिप्टेड निजी जगह में रहता है।')}</small>`);const token=sessionEpoch;d.querySelector('[data-sk-record]').onclick=async()=>{const node=d.querySelector('[data-sk-record-status]');if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){node.textContent=T('Recording unavailable. Import a file or write a note.','रिकॉर्डिंग उपलब्ध नहीं। फ़ाइल चुनें या लिखें।');return;}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(sessionEpoch!==token||modal!==d){stream.getTracks().forEach(t=>t.stop());return;}recordStream=stream;const chunks=[];recorder=new MediaRecorder(stream,{audioBitsPerSecond:24000});recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=async()=>{stream.getTracks().forEach(t=>t.stop());if(sessionEpoch!==token||modal!==d)return;const blob=new Blob(chunks,{type:recorder?.mimeType||chunks[0]?.type||'audio/webm'});if(blob.size>700000){node.textContent=T('That recording is too large. Try a shorter note.','रिकॉर्डिंग बड़ी है। छोटी रिकॉर्डिंग करें।');return;}recordedAudio=await asDataURL(blob);node.textContent=T('Voice note ready. Nothing uploaded.','आवाज़ तैयार है। कुछ अपलोड नहीं हुआ।');d.querySelector('[data-sk-record-stop]').disabled=true;d.querySelector('[data-sk-record]').disabled=false;};recorder.start();node.textContent=T('Recording · up to one minute','रिकॉर्डिंग · अधिकतम एक मिनट');d.querySelector('[data-sk-record-stop]').disabled=false;d.querySelector('[data-sk-record]').disabled=true;clearInterval(toolTimer);toolTimer=setTimeout(()=>{if(recorder?.state==='recording')recorder.stop();},60000);}catch{node.textContent=T('Microphone unavailable. You can still write or import audio.','माइक्रोफ़ोन उपलब्ध नहीं। लिख सकती हैं या ऑडियो चुन सकती हैं।');}};d.querySelector('[data-sk-record-stop]').onclick=()=>{clearTimeout(toolTimer);if(recorder?.state==='recording')recorder.stop();};d.querySelector('form').onsubmit=async e=>{e.preventDefault();if(recorder?.state==='recording')return;const form=e.target;try{let audio=recordedAudio;const file=form.elements.audio.files[0];if(file){if(!file.type.startsWith('audio/')||file.size>700000)throw Error(T('Choose an audio file up to 700 KB.','अधिकतम 700 KB का ऑडियो चुनें।'));audio=await asDataURL(file);}const body=form.elements.body.value.trim();if(!body&&!audio)throw Error(T('Add a note or a voice recording.','नोट या आवाज़ जोड़ें।'));if(data.letters.length>=20)throw Error(T('Keep up to 20 envelopes. Remove one before adding more.','अधिकतम 20 पत्र रखें। नया जोड़ने से पहले एक हटाएँ।'));data.letters.push({id:crypto.randomUUID(),title:form.elements.title.value,author:form.elements.author.value.trim(),body,audio:audio||null,date:M.today()});await save();closeModal();render();}catch(error){d.querySelector('[data-sk-record-status]').textContent=error.message;}};}
 function asDataURL(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read audio'));reader.readAsDataURL(blob);});}
 function openLetter(id){const letter=data.letters.find(l=>l.id===id);if(!letter)return;const d=showModal(`<span class="sk-eyebrow">${E(letter.author)}</span><h2>${E(letter.title)}</h2><p class="sk-letter-body">${E(letter.body)}</p>${letter.audio?'<audio controls data-sk-letter-audio></audio>':''}<button type="button" data-sk-letter-delete>${T('Delete this letter','यह पत्र हटाएँ')}</button>`);if(letter.audio&&/^data:audio\/[\w.+-]+(?:;[^,]*)?;base64,[A-Za-z0-9+/=]+$/.test(letter.audio))d.querySelector('audio').src=letter.audio;d.querySelector('[data-sk-letter-delete]').onclick=async()=>{data.letters=data.letters.filter(l=>l.id!==id);await save();closeModal();render();};}
 function startWizard(){wizard={index:-1,answers:Array(10).fill(null),postpartum:false};drawWizard();}
 function drawWizard(){if(!wizard)return;if(wizard.index===-1){const d=showModal(`<span class="sk-eyebrow">${T('Recovery check-in','रिकवरी चेक-इन')}</span><h2>${T('A standard check-in, at your pace.','एक मानक चेक-इन, आपकी गति पर।')}</h2><p>${T('This is the Edinburgh Postnatal Depression Scale (EPDS), a standard screening questionnaire used in postnatal care. It asks about the past seven days. It does not diagnose a condition.','यह एडिनबर्ग पोस्टनेटल डिप्रेशन स्केल (EPDS) है, प्रसव के बाद देखभाल में इस्तेमाल होने वाला मानक स्क्रीनिंग प्रश्नपत्र। यह पिछले सात दिनों के बारे में पूछता है। यह निदान नहीं करता।')}</p><p>${T('Answers stay in your encrypted space unless you explicitly choose to save a result to your clinical record and request review. Family never receives them.','जब तक आप स्पष्ट रूप से परिणाम क्लिनिकल रिकॉर्ड में सहेजकर समीक्षा नहीं माँगतीं, उत्तर आपकी एन्क्रिप्टेड जगह में रहते हैं। परिवार को नहीं मिलते।')}</p><p>${T('The validated instrument here is in English. We have not substituted an unvalidated Hindi translation. You may ask your care team for language support.','यहाँ मानक प्रश्नपत्र अंग्रेज़ी में है। हमने इसकी जगह अप्रमाणित हिंदी अनुवाद नहीं दिया है। अपनी देखभाल टीम से भाषा सहायता माँग सकती हैं।')}</p><label class="sk-check"><input type="checkbox" data-sk-afterbirth>${T('I am completing this after a birth.','मैं यह प्रसव के बाद भर रही हूँ।')}</label><button data-sk-wizard-begin class="sk-primary">${T('Begin ten questions','दस प्रश्न शुरू करें')}</button><small>Cox JL, Holden JM, Sagovsky R (1987). British Journal of Psychiatry, 150, 782–786. Prototype for clinical review.</small>`);d.querySelector('[data-sk-wizard-begin]').onclick=()=>{if(!d.querySelector('input').checked)return;wizard.postpartum=true;wizard.index=0;drawWizard();};return;}
  const i=wizard.index,[prompt,answers]=M.items[i];const d=showModal(`<span class="sk-eyebrow">${T('Question','प्रश्न')} ${i+1} / 10</span><p>${T('Think about the past seven days.','पिछले सात दिनों के बारे में सोचें।')}</p><fieldset class="sk-question"><legend lang="en">${E(prompt)}</legend>${answers.map((answer,index)=>`<label lang="en"><input type="radio" name="answer" value="${index}" ${wizard.answers[i]===index?'checked':''}>${E(answer)}</label>`).join('')}</fieldset><div class="sk-actions"><button data-sk-wizard-back>${T('Back','वापस')}</button><button class="sk-primary" data-sk-wizard-next>${i===9?T('Keep my check-in','अपना चेक-इन सहेजें'):T('Next','अगला')}</button></div><p data-sk-question-status role="status"></p>`);d.querySelectorAll('input').forEach(input=>input.onchange=()=>{wizard.answers[i]=+input.value;if(i===9&&+input.value!==3)void finishWizard(true);});d.querySelector('[data-sk-wizard-back]').onclick=()=>{wizard.index--;drawWizard();};d.querySelector('[data-sk-wizard-next]').onclick=async()=>{if(wizard.answers[i]===null){d.querySelector('[data-sk-question-status]').textContent=T('Choose the answer closest to your experience.','अपने अनुभव के सबसे करीब उत्तर चुनें।');return;}if(i===9)await finishWizard();else{wizard.index++;drawWizard();}};
 }
 async function finishWizard(urgent=false){if(!wizard||busy)return;busy=true;try{const result=M.scoreEPDS(wizard.answers);if(!result)return;data.checkins.push({id:crypto.randomUUID(),date:M.today(),answers:[...wizard.answers],postpartum:wizard.postpartum,result});if(urgent||result.itemTen>0){wizard=null;closeModal();crisis=true;render();try{await save();}catch{notice(T('The private copy could not be saved. Help remains available now.','निजी प्रति नहीं सहेजी गई। अभी मदद उपलब्ध है।'));}return;}await save();wizard=null;closeModal();render();showModal(`<span class="sk-eyebrow">${T('Thank you for checking in','बताने के लिए धन्यवाद')}</span><h2>${T('There is room for you here.','यहाँ आपके लिए जगह है।')}</h2><p>${T('Would you like to talk to someone about how you’ve been feeling? You can ask for support at any time.','आप कैसा महसूस कर रही हैं, क्या इस बारे में किसी से बात करना चाहेंगी? कभी भी सहारा माँग सकती हैं।')}</p><div class="sk-actions"><button data-sk-result-care>${T('Talk to my care team','देखभाल टीम से बात करें')}</button><button data-sk-result-trusted>${T('Someone I trust','कोई भरोसेमंद व्यक्ति')}</button><button data-sk-result-later>${T('Not now','अभी नहीं')}</button></div><a class="sk-button" href="tel:+9114416?oai_link_source=model_response_hotline">Tele-MANAS · 14416</a>`);modal.querySelector('[data-sk-result-care]').onclick=careOptions;modal.querySelector('[data-sk-result-later]').onclick=closeModal;modal.querySelector('[data-sk-result-trusted]')?.addEventListener('click',contactForm);}catch(error){const node=modal?.querySelector('[data-sk-question-status]');if(node)node.textContent=error.message;else notice(error.message);}finally{busy=false;}}
 function careOptions(){if(!data){notice(T('Open your private space, or use Appointments to arrange a conversation.','अपनी निजी जगह खोलें या अपॉइंटमेंट से बातचीत तय करें।'));navigate('appointments');return;}const latest=data.checkins.at(-1);const d=showModal(`<span class="sk-eyebrow">${T('Your choice, each time','हर बार आपकी पसंद')}</span><h2>${T('A conversation can start small.','बातचीत छोटी शुरुआत से हो सकती है।')}</h2><p>${T('Private notes and letters are never included. A chosen check-in is saved to DAI’s existing clinical record before an on-call review request is made. The assigned clinician receives your name, result and priority. Individual answers remain in the patient record, not the family view.','निजी नोट और पत्र शामिल नहीं होते। ऑन-कॉल समीक्षा अनुरोध से पहले चुना चेक-इन DAI के मौजूदा क्लिनिकल रिकॉर्ड में सहेजा जाता है। नियुक्त चिकित्सक को नाम, परिणाम और प्राथमिकता मिलती है। उत्तर मरीज के रिकॉर्ड में रहते हैं, परिवार के दृश्य में नहीं।')}</p>${latest?`<label class="sk-check"><input data-sk-review-consent type="checkbox">${T('Save this check-in to my clinical record and share the summary with an on-call clinician.','यह चेक-इन क्लिनिकल रिकॉर्ड में सहेजें और सार ऑन-कॉल चिकित्सक से साझा करें।')}</label><button data-sk-share-checkin class="sk-primary">${T('Confirm review request','समीक्षा अनुरोध की पुष्टि करें')}</button>`:`<button data-sk-care-checkin class="sk-primary">${T('Start a recovery check-in','रिकवरी चेक-इन शुरू करें')}</button>`}<button data-sk-care-book>${T('Arrange a conversation ↗','बातचीत तय करें ↗')}</button><button data-sk-care-history>${T('My shared requests','मेरे साझा अनुरोध')}</button><p data-sk-care-status role="status"></p><small>${T('Requests may wait for available coverage. This is not an emergency response or a promise of contact within a day.','कवरेज उपलब्ध होने तक अनुरोध प्रतीक्षा में रह सकता है। यह आपातकालीन सेवा या एक दिन में संपर्क का वादा नहीं है।')}</small>`);d.querySelector('[data-sk-care-book]').onclick=()=>{closeModal();navigate('appointments');};d.querySelector('[data-sk-care-checkin]')?.addEventListener('click',startWizard);d.querySelector('[data-sk-care-history]').onclick=sharedHistory;d.querySelector('[data-sk-share-checkin]')?.addEventListener('click',async()=>{if(!d.querySelector('[data-sk-review-consent]').checked)return;if(!real()){d.querySelector('[data-sk-care-status]').textContent=T('Sign in to request a clinician review. Your private check-in is kept on this device.','चिकित्सक समीक्षा के लिए साइन इन करें। निजी चेक-इन इस डिवाइस पर है।');return;}const button=d.querySelector('[data-sk-share-checkin]');button.disabled=true;try{if(!latest.clinical_id){const response=await api('/daicare/wellbeing/epds',{method:'POST',body:{answers:latest.answers,postpartum:true}});if(!response)throw Error(T('Could not save to the clinical record. Nothing was shared.','क्लिनिकल रिकॉर्ड में नहीं सहेजा गया। कुछ साझा नहीं हुआ।'));latest.clinical_id=response.screen.id;await save();}const result=await api('/daicare/wellbeing/epds/'+latest.clinical_id+'/referral',{method:'POST',body:{consent:true}});if(!result)throw Error(T('The result is in your clinical record, but the review request did not finish. Retry or contact your team.','परिणाम क्लिनिकल रिकॉर्ड में है, पर समीक्षा अनुरोध पूरा नहीं हुआ। फिर कोशिश करें या टीम से संपर्क करें।'));latest.shared=true;latest.shared_status=result.status;await save();d.querySelector('[data-sk-care-status]').textContent=result.status==='assigned'?T('Assigned. Waiting for clinician acknowledgement.','नियुक्त हुआ। चिकित्सक की पुष्टि की प्रतीक्षा है।'):T('Request recorded. Waiting for on-call coverage.','अनुरोध दर्ज है। ऑन-कॉल कवरेज की प्रतीक्षा है।');}catch(error){d.querySelector('[data-sk-care-status]').textContent=error.message;}finally{button.disabled=false;}});}
 async function sharedHistory(){const token=sessionEpoch,result=real()?await api('/daicare/wellbeing'):null;if(token!==sessionEpoch||!data)return;const screens=result?.screens||[];const d=showModal(`<h2>${T('Your shared requests','आपके साझा अनुरोध')}</h2>${screens.map(s=>`<article class="sk-request"><strong>${E(({waiting:T('Waiting for coverage','कवरेज की प्रतीक्षा'),assigned:T('Awaiting acknowledgement','चिकित्सक की पुष्टि की प्रतीक्षा'),acknowledged:T('Clinician acknowledged','चिकित्सक ने स्वीकार किया'),resolved:T('Follow-up note available','फॉलो-अप नोट उपलब्ध'),withdrawn:T('Sharing withdrawn','शेयरिंग वापस ली')})[s.referral_status]||T('Private clinical record','निजी क्लिनिकल रिकॉर्ड'))}</strong><small>${E(new Date(s.created_at).toLocaleDateString(language()))}</small>${s.clinician_note?`<p>${E(s.clinician_note)}</p>`:''}${s.referral_status&&s.referral_status!=='withdrawn'?`<button data-sk-withdraw="${E(s.id)}">${T('Withdraw this sharing','यह शेयरिंग वापस लें')}</button>`:''}</article>`).join('')||`<p>${T('No clinical check-ins recorded here yet.','यहाँ अभी क्लिनिकल चेक-इन दर्ज नहीं हैं।')}</p>`}<small>${T('Withdrawing access does not erase an existing clinical record.','पहुँच वापस लेने से मौजूदा क्लिनिकल रिकॉर्ड नहीं मिटता।')}</small>`);d.querySelectorAll('[data-sk-withdraw]').forEach(b=>b.onclick=async()=>{if(await api('/daicare/wellbeing/epds/'+b.dataset.skWithdraw+'/referral',{method:'DELETE'})){const found=data.checkins.find(c=>c.clinical_id===b.dataset.skWithdraw);if(found){found.shared=false;await save();}await sharedHistory();}});}
 let temporaryContact='';
 function contactForm(){const d=showModal(`<h2>${T('Someone you trust','कोई भरोसेमंद व्यक्ति')}</h2><form><label>${T('Their phone','उनका फोन')}<input name="phone" type="tel" maxlength="22" value="${E(data?.contacts?.phone||temporaryContact||'')}" required></label><label>${T('Hospital phone · optional','अस्पताल का फोन · वैकल्पिक')}<input name="hospital" type="tel" maxlength="22" value="${E(data?.contacts?.hospital||'')}"></label><p>${data?T('Kept in your encrypted space. Adding a contact does not grant record access.','आपकी एन्क्रिप्टेड जगह में रहता है। संपर्क जोड़ने से रिकॉर्ड की पहुँच नहीं मिलती।'):T('Used for this visit only. Unlock Sukoon to save a contact privately.','केवल इस सत्र में इस्तेमाल होगा। निजी रूप से सहेजने के लिए सुकून खोलें।')}</p><button class="sk-primary">${T('Keep this contact','यह संपर्क रखें')}</button><p role="status"></p></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.target;if(!/^[+\d ()-]{7,22}$/.test(f.phone.value)||(f.hospital.value&&!/^[+\d ()-]{7,22}$/.test(f.hospital.value))){d.querySelector('[role=status]').textContent=T('Check the phone number.','फोन नंबर जाँचें।');return;}temporaryContact=f.phone.value;if(data){data.contacts={phone:f.phone.value,hospital:f.hospital.value};try{await save();}catch(error){d.querySelector('[role=status]').textContent=error.message;return;}}closeModal();render();if(!crisis&&data)showModal(`<h2>${T('A familiar voice is one tap away.','एक परिचित आवाज़ एक टैप दूर है।')}</h2>${phoneLink(trustedPhone(),T('Call my person','अपने व्यक्ति को कॉल करें'))}`);};}
 function tapOut(){if(!real()||!config.people.length){showModal(`<h2>${T('Choose someone who can help.','कोई मददगार व्यक्ति चुनें।')}</h2><p>${T('An accepted Family Circle invitation with practical-support permission is needed. This app does not make an alarm call or silence your phone. You can contact your person directly.','व्यावहारिक सहयोग की अनुमति वाला स्वीकार किया गया Family Circle निमंत्रण चाहिए। ऐप अलार्म कॉल नहीं करता और फोन की आवाज़ बंद नहीं करता। अपने व्यक्ति से सीधे संपर्क कर सकती हैं।')}</p>${phoneLink(trustedPhone(),T('Call my chosen person','अपने चुने व्यक्ति को कॉल करें'))}<button data-sk-tap-family>${T('Open Family Circle','Family Circle खोलें')}</button>`);modal.querySelector('[data-sk-tap-family]').onclick=()=>{closeModal();navigate('family');};return;}
  const d=showModal(`<span class="sk-eyebrow">${T('Tap out','थोड़ा आराम माँगें')}</span><h2>${T('A practical request, nothing private.','व्यावहारिक अनुरोध, कोई निजी बात नहीं।')}</h2><form><label>${T('Ask this person','इस व्यक्ति से कहें')}<select name="person">${config.people.map(p=>`<option value="${E(p.id)}">${E(p.relationship+' · '+p.recipient_email)}</option>`).join('')}</select></label><label>${T('A rest period','आराम का समय')}<select name="minutes"><option value="30">30 ${T('minutes','मिनट')}</option><option value="60">60 ${T('minutes','मिनट')}</option><option value="120">120 ${T('minutes','मिनट')}</option></select></label><div class="sk-request-preview"><strong>${T('They will see','वे देखेंगे')}</strong><p>${T('“A little help tonight. Could you take a practical task while I rest?”','“आज रात थोड़ा सहारा चाहिए। मेरे आराम करने तक कोई व्यावहारिक काम सँभालेंगे?”')}</p></div><label class="sk-check"><input name="confirm" type="checkbox" required>${T('Send this practical request. No notes or check-in answers.','यह व्यावहारिक अनुरोध भेजें। नोट या चेक-इन उत्तर नहीं।')}</label><button class="sk-primary">${T('Send rest request','आराम अनुरोध भेजें')}</button><p role="status"></p><small>${T('In-app request only. It is not accepted until your person accepts it. Open request views refresh about every 15 seconds.','केवल इन-ऐप अनुरोध। व्यक्ति के स्वीकार करने तक स्वीकार नहीं माना जाता।')}</small></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button');button.disabled=true;try{const result=await api('/patient/sukoon/rest-requests',{method:'POST',body:{grant_id:form.person.value,minutes:+form.minutes.value,confirmed:form.confirm.checked}});if(!result){form.querySelector('[role=status]').textContent=T('Not sent. You can call your person directly.','नहीं भेजा गया। अपने व्यक्ति को कॉल कर सकती हैं।');return;}closeModal();tab='together';await refreshRemote();render();notice(T('Requested in their family space. No phone alarm or push was sent.','उनकी पारिवारिक जगह में अनुरोध दर्ज है। फोन अलार्म या पुश नहीं भेजा गया।'));}finally{button.disabled=false;}};
 }
 function summary(){const recent=M.weekly(data.entries,M.today()).filter(day=>day.entry),chosen=data.checkins.filter(c=>c.shared);const text=[T('Sukoon · Recovery summary','सुकून · रिकवरी सार'),T('Self-reported entries, not a diagnosis.','स्वयं दर्ज बातें, निदान नहीं।'),T('Recorded week','दर्ज सप्ताह')+': '+M.today(),...recent.map(day=>day.date+' · '+label(day.entry.weather)),T('Check-ins chosen for clinical review','क्लिनिकल समीक्षा के लिए चुने चेक-इन')+': '+chosen.map(c=>c.date).join(', '),T('Private notes and letters are excluded. No clinical scores included.','निजी नोट और पत्र शामिल नहीं। क्लिनिकल अंक शामिल नहीं।')].join('\n');const d=showModal(`<h2>${T('Review before sharing','साझा करने से पहले देखें')}</h2><p>${T('This download includes only the information shown below. You decide who receives it.','डाउनलोड में केवल नीचे की जानकारी है। किसे देना है, यह आप चुनती हैं।')}</p><pre class="sk-summary">${E(text)}</pre><button class="sk-primary" data-sk-summary-download>${T('Download this summary','यह सार डाउनलोड करें')}</button>`);d.querySelector('[data-sk-summary-download]').onclick=()=>download(text,'sukoon-recovery-summary.txt','text/plain');}
 function download(text,name,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
 async function backup(){if(!real())return;const token=sessionEpoch,result=await api('/patient/sukoon/vault');if(token!==sessionEpoch||!data||!result)return;const existing=result.backup,expected=existing?.revision||null;const d=showModal(`<h2>${T('Encrypted backup','एन्क्रिप्टेड बैकअप')}</h2><p>${T('Only ciphertext is uploaded. Your passphrase and decryption key stay on your device. You need the same passphrase to restore it.','केवल एन्क्रिप्टेड डेटा अपलोड होता है। पासफ़्रेज़ और कुंजी डिवाइस पर रहती हैं। वापस खोलने के लिए वही पासफ़्रेज़ चाहिए।')}</p><label class="sk-check"><input type="checkbox" data-sk-backup-confirm>${existing?T('Replace the existing backup with this device’s copy.','मौजूदा बैकअप को इस डिवाइस की प्रति से बदलें।'):T('Save an encrypted backup to my DAI account.','मेरे DAI खाते में एन्क्रिप्टेड बैकअप सहेजें।')}</label><button class="sk-primary" data-sk-backup-send>${T('Confirm encrypted backup','एन्क्रिप्टेड बैकअप की पुष्टि करें')}</button><p role="status"></p>`);d.querySelector('[data-sk-backup-send]').onclick=async()=>{if(!d.querySelector('input').checked)return;const envelope=vault.encrypted();if(!envelope)return;const saved=await api('/patient/sukoon/vault',{method:'PUT',body:{envelope,revision:envelope.revision,expected_revision:expected}});if(saved){cloudRevision=saved.revision;d.querySelector('[role=status]').textContent=T('Encrypted backup saved.','एन्क्रिप्टेड बैकअप सहेजा गया।');}};}
 async function restore(){if(!real())return;const token=sessionEpoch,result=await api('/patient/sukoon/vault');if(token!==sessionEpoch||!result)return;if(!result.backup){notice(T('No encrypted backup is recorded.','एन्क्रिप्टेड बैकअप दर्ज नहीं है।'));return;}const d=showModal(`<h2>${T('Restore your encrypted copy','अपनी एन्क्रिप्टेड प्रति वापस लाएँ')}</h2><p>${T('This replaces this browser’s private copy and locks it. You will need the backup’s passphrase. Download your current encrypted copy first if you want to keep both.','यह ब्राउज़र की निजी प्रति बदलकर लॉक कर देगा। बैकअप का पासफ़्रेज़ चाहिए। दोनों प्रतियाँ रखने के लिए पहले वर्तमान एन्क्रिप्टेड प्रति डाउनलोड करें।')}</p><label class="sk-check"><input type="checkbox">${T('Replace this device’s copy with my backup.','इस डिवाइस की प्रति बैकअप से बदलें।')}</label><button data-sk-restore-confirm>${T('Restore and lock','वापस लाकर लॉक करें')}</button><p role="status"></p>`);d.querySelector('[data-sk-restore-confirm]').onclick=async()=>{if(!d.querySelector('input').checked)return;try{await vault.restore(result.backup.envelope);cloudRevision=result.backup.revision;exists=true;lock();}catch(error){d.querySelector('[role=status]').textContent=error.message;}};}
 function erase(){const d=showModal(`<h2>${T('Your private copies','आपकी निजी प्रतियाँ')}</h2><p>${T('Choose what to delete. Already shared clinical records follow care-record retention rules and are not erased here.','क्या हटाना है चुनें। पहले साझा किए क्लिनिकल रिकॉर्ड के संरक्षण नियम अलग हैं; वे यहाँ नहीं मिटते।')}</p><label class="sk-check"><input type="checkbox" data-sk-erase-local>${T('Delete this device’s encrypted Sukoon copy.','इस डिवाइस की एन्क्रिप्टेड सुकून प्रति हटाएँ।')}</label><label class="sk-check"><input type="checkbox" data-sk-erase-cloud ${!real()?'disabled':''}>${T('Delete my encrypted server backup.','मेरा एन्क्रिप्टेड सर्वर बैकअप हटाएँ।')}</label><button data-sk-erase-confirm>${T('Delete the selected copies','चुनी प्रतियाँ हटाएँ')}</button><p role="status"></p>`);d.querySelector('[data-sk-erase-confirm]').onclick=async()=>{const local=d.querySelector('[data-sk-erase-local]').checked,cloud=d.querySelector('[data-sk-erase-cloud]').checked;if(!local&&!cloud)return;if(cloud&&!await api('/patient/sukoon/vault',{method:'DELETE'})){d.querySelector('[role=status]').textContent=T('Could not delete the server backup. No local copy was removed.','सर्वर बैकअप नहीं हट पाया। स्थानीय प्रति नहीं हटाई गई।');return;}if(local){await vault.remove();exists=false;lock();}else{closeModal();notice(T('Encrypted server backup deleted.','एन्क्रिप्टेड सर्वर बैकअप हटाया गया।'));}};}
 async function action(name){switch(name){case 'hide':lock(true);break;case 'help':crisis=true;render();break;case 'sos':document.getElementById('sosBtn')?.click();break;case 'back':crisis=false;render();break;case 'trusted':contactForm();break;case 'care':careOptions();break;case 'later':notice(T('Whenever you are ready. This space stays here.','जब आप तैयार हों। यह जगह यहीं है।'));break;case 'breathing':breathing();break;case 'grounding':grounding();break;case 'sleep':sleepTimer();break;case 'newletter':letterForm();break;case 'wizard':startWizard();break;case 'tapout':tapOut();break;case 'family':navigate('family');break;case 'earlier':weekOffset++;render();break;case 'newer':weekOffset=Math.max(0,weekOffset-1);render();break;case 'nightdim':night=!night;render();break;case 'backup':await backup();break;case 'restore':await restore();break;case 'summary':summary();break;case 'export':download(JSON.stringify(vault.encrypted()),'sukoon-encrypted.json');break;case 'erase':erase();break;}}
 async function onClick(event){lastTouch=Date.now();const b=event.target.closest('button');if(!b)return;try{if(b.dataset.skAction)await action(b.dataset.skAction);else if(b.dataset.skTab){stopTools();tab=b.dataset.skTab;night=tab==='night';render();if(tab==='together')await refreshRemote();}else if(b.dataset.skWeather){selected=b.dataset.skWeather;const note=$('[data-sk-form=mood] input')?.value;render();if(note&&$('[data-sk-form=mood] input'))$('[data-sk-form=mood] input').value=note;}else if(b.dataset.skDay){const entry=data.entries.find(e=>e.date===b.dataset.skDay);showModal(`<h2>${E(b.dataset.skDay)}</h2><p>${entry?E(label(entry.weather)):T('Nothing recorded. There is no missing-day penalty.','कुछ दर्ज नहीं। दिन छूटने पर कोई दंड नहीं।')}</p>${entry?.note?`<p class="sk-letter-body">${E(entry.note)}</p>`:''}`);}else if(b.dataset.skLetter)openLetter(b.dataset.skLetter);else if(b.dataset.skStory!==undefined){const story=M.stories[+b.dataset.skStory];showModal(`<h2>${E(story.title[language()==='hi'?1:0])}</h2><p class="sk-transcript">${E(story.text[language()==='hi'?1:0])}</p><p data-sk-audio-status role="status"></p><button data-sk-story-play>${T('Play prepared story','तैयार कहानी सुनें')}</button><small>${T('Fictional prototype story · not a real mother’s testimony.','प्रोटोटाइप उदाहरण कहानी · किसी माँ की वास्तविक गवाही नहीं।')}</small>`);modal.querySelector('[data-sk-story-play]').onclick=()=>playPrepared(story.text[language()==='hi'?1:0]);}else if(b.dataset.skDuty){if(real()){if(!await api('/patient/sukoon/duties',{method:'POST',body:{kind:b.dataset.skDuty}}))return;await refreshRemote();}else{data.duties.push({id:crypto.randomUUID(),kind:b.dataset.skDuty,person:'mother',created_at:new Date().toISOString()});await save();}render();notice(T('Recorded as your self-reported task.','आपके स्वयं दर्ज काम के रूप में सहेजा गया।'));}else if(b.dataset.skCancel){if(await api('/patient/sukoon/rest-requests/'+b.dataset.skCancel,{method:'DELETE'}))await refreshRemote();}}catch(error){notice(error.message||T('Could not complete that action.','कार्रवाई पूरी नहीं हुई।'));}}
 async function onSubmit(event){const form=event.target;if(!form.dataset.skForm)return;event.preventDefault();if(busy)return;busy=true;try{if(form.dataset.skForm==='unlock'){if(!exists&&(form.pass.value!==form.repeat.value||!form.device.checked))throw Error(T('Repeat the same passphrase and confirm your private device.','एक ही पासफ़्रेज़ दोहराएँ और निजी डिवाइस की पुष्टि करें।'));const token=sessionEpoch,instance=vault,pass=form.pass.value;form.reset();const unlocked=await instance.unlock(pass,{create:!exists});if(token!==sessionEpoch||!active())return;data=unlocked;exists=true;lastTouch=Date.now();render();await refreshRemote();}else if(form.dataset.skForm==='mood'){if(!selected)throw Error(T('Choose the weather closest to today.','आज के अनुभव के सबसे करीब मौसम चुनें।'));const note=form.note.value.trim();data.entries=data.entries.filter(e=>e.date!==M.today());data.entries.push({date:M.today(),weather:selected,note});if(M.urgentDisclosure(note)){crisis=true;render();try{await save();}catch{notice(T('The private copy could not be saved. Help remains available now.','निजी प्रति नहीं सहेजी गई। अभी मदद उपलब्ध है।'));}}else{await save();render();notice(T('Kept privately. Thank you for telling me.','निजी रूप से सहेजा। बताने के लिए धन्यवाद।'));}}}catch(error){notice(error.message);}finally{busy=false;}}
 async function onChange(event){lastTouch=Date.now();try{if(event.target.matches('[data-sk-reminder]')){const result=await api('/patient/sukoon/preferences',{method:'PUT',body:{reminders:event.target.checked}});if(result){config.reminders=result.reminders;notice(T('In-app reminder choice saved. No SMS or push enabled.','इन-ऐप याद दिलाने की पसंद सहेजी। SMS या पुश चालू नहीं।'));}}if(event.target.matches('[data-sk-presence]')){const checked=event.target.checked,result=await api('/patient/sukoon/presence',{method:checked?'POST':'DELETE',...(checked?{body:{consent:true}}:{})});joined=!!result&&checked;clearTimeout(presenceTimer);if(joined)presenceTimer=setTimeout(()=>{joined=false;if($('[data-sk-presence]'))$('[data-sk-presence]').checked=false;void refreshAwake();},300000);if(!result)event.target.checked=false;await refreshAwake();}}catch{notice(T('Could not save this choice.','यह पसंद नहीं सहेजी गई।'));}}
 async function update(next){state=next||{};const nextOwner=(guest()?'guest':state.user?.id)||'guest',changed=owner!==nextOwner;if(changed){lock();owner=nextOwner;sessionEpoch++;config={people:[],reminders:false,awake_available:false};household={requests:[],duties:[]};vault=window.createSukoonVault(owner);const token=sessionEpoch;exists=await vault.exists();if(token!==sessionEpoch)return;}if(active()){mount();if(changed)render();}}
 function mount(){const host=document.getElementById('patientSukoon');if(!host)return;if(!root){root=host;root.classList.add('sk-page');root.addEventListener('click',onClick);root.addEventListener('submit',onSubmit);root.addEventListener('change',onChange);root.addEventListener('keydown',()=>lastTouch=Date.now());voice=window.createMirrorVoice?.({url:'/api/tts',active:()=>!!data&&active()&&!muted&&!document.hidden,onState:voiceState});}if(!root.childElementCount)render();if(!owner){void update(state).catch(()=>notice(T('Private storage is unavailable here.','यहाँ निजी भंडारण उपलब्ध नहीं है।')));return;}void refreshRemote();}
 function sync(){if(active())mount();else if(data||modal)lock();}
 window.PatientSukoon={update:next=>update(next).catch(()=>notice(T('Private storage is unavailable. Use Help now or try a private device.','निजी भंडारण उपलब्ध नहीं। अभी मदद लें या निजी डिवाइस पर कोशिश करें।'))),lock:()=>lock()};window.addEventListener('hashchange',sync);window.addEventListener('dai:patient-panel',sync);window.addEventListener('dai:lang',()=>{closeModal();if(active())render();});window.addEventListener('pagehide',()=>lock());document.addEventListener('visibilitychange',()=>{if(document.hidden)lock();});document.addEventListener('pointerdown',event=>{if(event.target.closest('#patientSukoon,.sk-dialog'))lastTouch=Date.now();});document.addEventListener('keydown',event=>{if(event.target.closest('#patientSukoon,.sk-dialog'))lastTouch=Date.now();});setInterval(()=>{if(data&&Date.now()-lastTouch>300000)lock();else if(data&&active()&&tab==='together'&&!modal&&Date.now()-lastRemote>15000)void refreshRemote();},15000);
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',sync,{once:true});else sync();
})();
